const SCHEMA = "CREATE TABLE IF NOT EXISTS app_state (key TEXT PRIMARY KEY, payload TEXT NOT NULL, updated_at INTEGER NOT NULL DEFAULT 0)";
const MEDIA_SCHEMA = "CREATE TABLE IF NOT EXISTS app_media (id TEXT PRIMARY KEY, content_type TEXT NOT NULL, body BLOB NOT NULL, updated_at INTEGER NOT NULL DEFAULT 0)";

function envValue(env, key) {
  if (env && env[key] != null && String(env[key]) !== "") return env[key];
  if (typeof process !== "undefined" && process.env && process.env[key] != null) return process.env[key];
  return "";
}

function databaseBinding(env) {
  return env && env.DB && typeof env.DB.prepare === "function" ? env.DB : null;
}

function supabaseConfig(env) {
  const url = String(envValue(env, "SUPABASE_URL") || "").replace(/\/$/, "");
  const key = String(envValue(env, "SUPABASE_SERVICE_ROLE_KEY") || "");
  const table = String(envValue(env, "SUPABASE_TABLE") || "hazeyn_data").replace(/[^a-z0-9_]/gi, "") || "hazeyn_data";
  const rowId = String(envValue(env, "SUPABASE_ROW_ID") || "main");
  const bucket = String(envValue(env, "SUPABASE_BUCKET") || "hazeyn").replace(/[^a-z0-9_.-]/gi, "") || "hazeyn";
  return { url, key, table, rowId, bucket, ready: Boolean(url && key) };
}

function supabaseHeaders(config, extra = {}) {
  return { apikey: config.key, authorization: "Bearer " + config.key, ...extra };
}

async function readSupabaseState(env) {
  const config = supabaseConfig(env);
  if (!config.ready) return null;
  const endpoint = config.url + "/rest/v1/" + config.table + "?id=eq." + encodeURIComponent(config.rowId) + "&select=data&limit=1";
  const response = await fetch(endpoint, { headers: supabaseHeaders(config, { accept: "application/json" }) });
  if (!response.ok) throw new Error("Supabase veri okuma hatasi: " + response.status);
  const rows = await response.json();
  if (!Array.isArray(rows) || !rows[0] || rows[0].data == null) return null;
  return typeof rows[0].data === "string" ? rows[0].data : JSON.stringify(rows[0].data);
}

async function writeSupabaseState(env, payload) {
  const config = supabaseConfig(env);
  if (!config.ready) return false;
  const endpoint = config.url + "/rest/v1/" + config.table;
  const response = await fetch(endpoint, {
    method: "POST",
    headers: supabaseHeaders(config, {
      "content-type": "application/json",
      prefer: "resolution=merge-duplicates,return=minimal"
    }),
    body: JSON.stringify({ id: config.rowId, data: JSON.parse(payload), updated_at: new Date().toISOString() })
  });
  if (!response.ok) throw new Error("Supabase veri kayit hatasi: " + response.status + " " + await response.text());
  return true;
}

function json(data, status = 200) {
  return new Response(JSON.stringify(data), { status, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" } });
}

async function ensureLocalState(env) {
  const db = databaseBinding(env);
  if (!db) return DEFAULT_DATA;
  await db.prepare(SCHEMA).run();
  const row = await db.prepare("SELECT payload FROM app_state WHERE key = ?").bind("main").first();
  if (row && row.payload) {
    try {
      const oldData = JSON.parse(row.payload);
      const banners = Array.isArray(oldData?.settings?.heroBanners) ? oldData.settings.heroBanners : [];
      const gallery = Array.isArray(oldData?.gallery) ? oldData.gallery : [];
      const isEmptyLegacyDefault = !oldData?._meta?.updatedAt
        && banners.length === 1 && banners[0]?.image === "assets/hero.svg"
        && gallery.length === 3
        && gallery.some(item => item?.image === "assets/hotel.svg")
        && gallery.some(item => item?.image === "assets/yurtici.svg");
      if (!isEmptyLegacyDefault) return row.payload;
      await db.prepare("UPDATE app_state SET payload = ?, updated_at = ? WHERE key = ?").bind(DEFAULT_DATA, Date.now(), "main").run();
      return DEFAULT_DATA;
    } catch {
      return row.payload;
    }
  }
  await db.prepare("INSERT OR IGNORE INTO app_state (key, payload, updated_at) VALUES (?, ?, ?)").bind("main", DEFAULT_DATA, Date.now()).run();
  return DEFAULT_DATA;
}

async function ensureState(env) {
  try {
    const remote = await readSupabaseState(env);
    if (remote) return { payload: remote, source: "supabase" };
  } catch (error) {
    console.error("Supabase okuma basarisiz, yerel yedek kullaniliyor.", error);
  }
  return { payload: await ensureLocalState(env), source: "local" };
}

function decodeBase64(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

const FALLBACK_ADMIN_PASSWORD_SHA256 = "4715441fb3d9f3ee5ce2f74cd2752f45e4fb0d5a381cd532e8cab562fd99d83a";
const PUBLIC_SETTING_KEYS = ["brand","phone","phone2","whatsapp","email","website","instagram","address","heroTitle","heroSubtitle","heroMode","heroBanners","staffBannerKicker","staffBannerTitle","staffBannerSubtitle","staffBannerImage","blogBannerKicker","blogBannerTitle","blogBannerSubtitle","blogBannerImage","searchConsoleVerification","googleSiteVerification","googleMapsEmbedUrl","mapsEmbedUrl","mapUrl","officeImages","officePhotos","ga4MeasurementId","googleAnalyticsId","gaMeasurementId","metaPixelId","facebookPixelId","googleAdsId","googleAdsConversionId","googleAdsWhatsappLabel","whatsappConversionLabel","googleAdsPhoneLabel","phoneConversionLabel","googleAdsFormLabel","formConversionLabel","contactConversionLabel"];

function constantTimeEqual(left, right) {
  const a = String(left || "");
  const b = String(right || "");
  if (!a || a.length !== b.length) return false;
  let difference = 0;
  for (let i = 0; i < a.length; i += 1) difference |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return difference === 0;
}

async function sha256(value) {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(String(value || "")));
  return Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, "0")).join("");
}

async function verifyAdminCredential(env, value) {
  const candidate = String(value || "");
  if (!candidate) return false;
  const configured = String(envValue(env, "HAZEYN_ADMIN_PASSWORD") || envValue(env, "ADMIN_PASSWORD") || "");
  if (configured) return constantTimeEqual(candidate, configured);
  return constantTimeEqual(await sha256(candidate), String(envValue(env, "HAZEYN_ADMIN_PASSWORD_SHA256") || FALLBACK_ADMIN_PASSWORD_SHA256));
}

function requestCredential(request) {
  const direct = String(request.headers.get("x-admin-password") || "");
  const authorization = String(request.headers.get("authorization") || "");
  return direct || (authorization.startsWith("Bearer ") ? authorization.slice(7) : "");
}

function sanitizeAdminState(input) {
  const state = JSON.parse(JSON.stringify(input || {}));
  delete state.adminPassword;
  if (state.settings) {
    delete state.settings.adminPassword;
    delete state.settings.password;
    delete state.settings.serviceRoleKey;
    delete state.settings.privateKey;
    delete state.settings.secret;
    delete state.settings.accessToken;
    delete state.settings.refreshToken;
  }
  return state;
}

function sanitizePublicState(input) {
  const state = sanitizeAdminState(input);
  const settings = {};
  PUBLIC_SETTING_KEYS.forEach(key => {
    if (Object.prototype.hasOwnProperty.call(state.settings || {}, key)) settings[key] = state.settings[key];
  });
  const items = key => (Array.isArray(state[key]) ? state[key] : []).filter(item => !(item && (item.status === "draft" || item.published === false)));
  const output = {_meta:{updatedAt:Number(state._meta?.updatedAt || 0)}, settings, tours:items("tours"), reviews:items("reviews"), gallery:items("gallery"), staff:items("staff"), blogs:items("blogs")};
  if (Array.isArray(state.banners)) output.banners = items("banners");
  return output;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname.startsWith("/media/") && request.method === "GET") {
      const db = databaseBinding(env);
      if (!db) return new Response("Görsel bulunamadı", { status: 404 });
      await db.prepare(MEDIA_SCHEMA).run();
      const id = url.pathname.slice("/media/".length).replace(/[^a-z0-9-]/gi, "");
      const row = id ? await db.prepare("SELECT content_type, body FROM app_media WHERE id = ?").bind(id).first() : null;
      if (!row || !row.body) return new Response("Görsel bulunamadı", { status: 404 });
      return new Response(row.body, { headers: { "content-type": row.content_type, "cache-control": "public, max-age=31536000, immutable" } });
    }
    if (url.pathname === "/api/data" && request.method === "GET") {
      const isAdmin = await verifyAdminCredential(env, requestCredential(request));
      const wantsAdmin = url.searchParams.get("scope") === "admin";
      if (wantsAdmin && !isAdmin) return json({ ok: false, error: "Yetkisiz." }, 401);
      if (url.searchParams.get("action") === "upload-config") {
        if (!isAdmin) return json({ ok: false, error: "Yetkisiz." }, 401);
        const config = supabaseConfig(env);
        return json({ url: config.url, anonKey: String(envValue(env, "SUPABASE_ANON_KEY") || ""), bucket: config.bucket });
      }
      const state = await ensureState(env);
      const parsed = JSON.parse(state.payload || "{}");
      const payload = isAdmin ? sanitizeAdminState(parsed) : sanitizePublicState(parsed);
      return new Response(JSON.stringify(payload), { headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store", "x-hazeyn-data-source": state.source } });
    }
    if (url.pathname === "/api/login" && request.method === "POST") {
      const body = await request.json().catch(() => ({}));
      return await verifyAdminCredential(env, body.password) ? json({ ok: true }) : json({ ok: false, error: "Şifre hatalı." }, 401);
    }
    if (url.pathname === "/api/media-upload" && request.method === "POST") {
      if (!await verifyAdminCredential(env, requestCredential(request))) return json({ ok: false, error: "Yetkisiz." }, 401);
      const body = await request.arrayBuffer();
      if (!body.byteLength || body.byteLength > 1800000) return json({ ok: false, error: "Görsel en fazla 1,8 MB olabilir." }, 413);
      const contentType = String(request.headers.get("content-type") || "image/jpeg");
      if (!contentType.startsWith("image/")) return json({ ok: false, error: "Geçersiz görsel." }, 415);
      const id = crypto.randomUUID();
      const config = supabaseConfig(env);
      if (config.ready) {
        const requestedFolder = String(request.headers.get("x-upload-folder") || "uploads").replace(/[^a-z0-9_-]/gi, "-") || "uploads";
        const originalName = String(request.headers.get("x-file-name") || "image.jpg");
        const originalExt = (originalName.match(/\.([a-z0-9]{2,5})$/i) || [])[1];
        const mimeExt = contentType.includes("png") ? "png" : contentType.includes("webp") ? "webp" : contentType.includes("gif") ? "gif" : "jpg";
        const extension = String(originalExt || mimeExt).replace(/[^a-z0-9]/gi, "").toLowerCase() || mimeExt;
        const objectPath = requestedFolder + "/" + new Date().toISOString().slice(0, 10) + "/" + id + "." + extension;
        const upload = await fetch(config.url + "/storage/v1/object/" + config.bucket + "/" + objectPath, {
          method: "POST",
          headers: supabaseHeaders(config, { "content-type": contentType, "x-upsert": "false" }),
          body
        });
        if (!upload.ok) return json({ ok: false, error: "Gorsel Supabase'e yuklenemedi (" + upload.status + ")." }, 502);
        return json({ ok: true, url: config.url + "/storage/v1/object/public/" + config.bucket + "/" + objectPath });
      }
      const db = databaseBinding(env);
      if (!db) return json({ ok: false, error: "Görsel depolama ayarı bulunamadı." }, 503);
      await db.prepare(MEDIA_SCHEMA).run();
      await db.prepare("INSERT INTO app_media (id, content_type, body, updated_at) VALUES (?, ?, ?, ?)").bind(id, contentType, body, Date.now()).run();
      return json({ ok: true, url: "/media/" + id });
    }
    if (url.pathname === "/api/data" && request.method === "POST") {
      if (!await verifyAdminCredential(env, requestCredential(request))) return json({ ok: false, error: "Yetkisiz." }, 401);
      const rawPayload = await request.text();
      let payload;
      try { payload = JSON.stringify(sanitizeAdminState(JSON.parse(rawPayload))); } catch { return json({ ok: false, error: "Geçersiz veri." }, 400); }
      try {
        if (await writeSupabaseState(env, payload)) {
          try {
            const db = databaseBinding(env);
            if (db) {
              await db.prepare(SCHEMA).run();
              await db.prepare("INSERT INTO app_state (key, payload, updated_at) VALUES (?, ?, ?) ON CONFLICT(key) DO UPDATE SET payload = excluded.payload, updated_at = excluded.updated_at").bind("main", payload, Date.now()).run();
            }
          } catch (error) {
            console.error("Yerel yedek kaydi basarisiz.", error);
          }
          return json({ ok: true, source: "supabase" });
        }
      } catch (error) {
        console.error("Supabase kaydi basarisiz.", error);
        return json({ ok: false, error: "Merkezi veri kaydi yapilamadi." }, 502);
      }
      const db = databaseBinding(env);
      if (!db) return json({ ok: false, error: "Merkezi veri kaydı yapılandırılmamış." }, 503);
      await db.prepare("INSERT INTO app_state (key, payload, updated_at) VALUES (?, ?, ?) ON CONFLICT(key) DO UPDATE SET payload = excluded.payload, updated_at = excluded.updated_at").bind("main", payload, Date.now()).run();
      return json({ ok: true });
    }
    if (url.pathname.startsWith("/api/")) return json({ ok: false, error: "Bu işlem bu sürümde kullanılamıyor." }, 404);

    const routes = { "/": "/index.html", "/tr": "/index.html", "/tr/": "/index.html", "/admin": "/admin.html", "/deneyimli-kadro": "/deneyimli-kadro.html", "/merak-edilenler": "/merak-edilenler.html" };
    const asset = ASSETS[routes[url.pathname] || url.pathname];
    if (!asset) return new Response("Sayfa bulunamadı", { status: 404 });
    return new Response(decodeBase64(asset.body), { headers: { "content-type": asset.type, "cache-control": asset.type.startsWith("text/html") ? "no-cache" : "public, max-age=86400" } });
  }
};
